mapper.select:
SELECT al.activity_log_id AS activityLogId, UPPER(al.act) AS action, al.resource_id AS resourceId, al.resource_name AS resourceName, al.field AS fieldName, al.before_value AS beforeValue, al.after_value AS afterValue, al.user_id AS actorUserId, e.name AS actorName, b.block_id AS blockId, b.title AS blockTitle, b.type AS blockType, al.created_at AS createdAt FROM activity_log al JOIN block b ON b.block_id = al.block_id JOIN employee e ON e.user_id = al.user_id WHERE b.step_id = #{stepId} AND al.block_id IS NOT NULL
AND al.block_id = #{blockId}
AND al.activity_log_id < #{cursor}
ORDER BY al.activity_log_id DESC LIMIT #{limit}
